import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Button, Card, IconButton, Tooltip, TextField, Box } from '@mui/material';
import { DataGrid } from '@mui/x-data-grid';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import DownloadIcon from '@mui/icons-material/Download';
import { toast } from 'react-toastify';
import { getAllExpenses, deleteExpense, getExpenseExport } from '../../apis/expenseSlice';
import ExpenseDialog from './ExpenseDialog';
import { exportExpensesToExcel } from '../../utils/expenseExport';
import moment from 'moment';
import styles from './expense.module.scss';

const ExpensePage = () => {
  const dispatch = useDispatch();
  const { expenses, expenseLoading, total } = useSelector((state) => state.expenseData);

  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(10);
  const [open, setOpen] = useState(false);
  const [editData, setEditData] = useState(null);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [description, setDescription] = useState('');
  const [exportLoading, setExportLoading] = useState(false);

  useEffect(() => {
    callApi();
  }, [page, pageSize]);

  const callApi = () => {
    dispatch(getAllExpenses({ page, pageSize }));
  };

  const handleEdit = (data) => {
    setEditData(data);
    setOpen(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this expense?')) {
      const response = await dispatch(deleteExpense(id));
      if (!response.payload?.error) {
        toast.success('Expense deleted successfully');
        callApi();
      }
    }
  };

  const handleExportToExcel = async () => {
    try {
      setExportLoading(true);
      
      // Build filter parameters
      const filterParams = {};
      if (startDate) filterParams.startDate = startDate;
      if (endDate) filterParams.endDate = endDate;
      if (description) filterParams.description = description;

      // Call the export API
      const response = await dispatch(getExpenseExport(filterParams));
      
      if (response.payload?.success) {
        const fileName = `Expenses_${moment().format('DD-MM-YYYY')}`;
        const filterDetails = {
          startDate: startDate || null,
          endDate: endDate || null,
          description: description || null,
        };
        
        exportExpensesToExcel(response.payload.data, fileName, filterDetails);
        toast.success('Expenses exported successfully');
      } else {
        toast.error('Failed to export expenses');
      }
    } catch (error) {
      console.error('Export error:', error);
      toast.error('Error exporting expenses');
    } finally {
      setExportLoading(false);
    }
  };

  const handleClearFilters = () => {
    setStartDate('');
    setEndDate('');
    setDescription('');
  };

  const columns = [
    {
      field: 'actions',
      headerName: 'Actions',
      width: 150,
      sortable: false,
      renderCell: (params) => (
        <div>
          <Tooltip title="Edit">
            <IconButton onClick={() => handleEdit(params.row)} color="primary" size="small">
              <EditIcon />
            </IconButton>
          </Tooltip>
          <Tooltip title="Delete">
            <IconButton onClick={() => handleDelete(params.row._id)} color="error" size="small">
              <DeleteIcon />
            </IconButton>
          </Tooltip>
        </div>
      ),
    },
    {
      field: 'description',
      headerName: 'Description',
      width: 200,
    },
    {
      field: 'category',
      headerName: 'Category',
      width: 150,
      renderCell: (params) => (
        <span style={{ textTransform: 'capitalize' }}>
          {params.row.category}
        </span>
      ),
    },
    {
      field: 'amount',
      headerName: 'Amount',
      width: 120,
      renderCell: (params) => <span>₹ {params.row.amount.toFixed(2)}</span>,
    },
    {
      field: 'expenseDate',
      headerName: 'Date',
      width: 150,
      renderCell: (params) => moment(params.row.expenseDate).format('DD/MM/YYYY'),
    },
  ];

  return (
    <div>
      <Card className={styles.tableCard}>
        <div className={styles.tableHeader}>
          <h2 className={styles.tableTitle}>Expenses</h2>
          <Button
            className={styles.addBtn}
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => {
              setEditData(null);
              setOpen(true);
            }}
          >
            Add Expense
          </Button>
        </div>

        {/* Filter Section */}
        <Box sx={{ p: 2, backgroundColor: '#f5f5f5', borderBottom: '1px solid #ddd', mb: 2 }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '16px', marginBottom: '16px' }}>
            <TextField
              label="Start Date"
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              InputLabelProps={{
                shrink: true,
              }}
              size="small"
            />
            <TextField
              label="End Date"
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              InputLabelProps={{
                shrink: true,
              }}
              size="small"
            />
            <TextField
              label="Search Description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Search by description..."
              size="small"
            />
          </div>

          <div style={{ display: 'flex', gap: '8px' }}>
            <Button
              variant="contained"
              color="primary"
              startIcon={<DownloadIcon />}
              onClick={handleExportToExcel}
              disabled={exportLoading}
              sx={{
                backgroundColor: '#4CAF50',
                '&:hover': {
                  backgroundColor: '#45a049',
                },
              }}
            >
              {exportLoading ? 'Exporting...' : 'Export to Excel'}
            </Button>
            <Button
              variant="outlined"
              onClick={handleClearFilters}
            >
              Clear Filters
            </Button>
          </div>
        </Box>
        <DataGrid
          sx={{
            color: '#000',
            backgroundColor: '#fff',
            fontSize: '1rem',
            height: 'auto',
          }}
          rows={expenses || []}
          columns={columns}
          loading={expenseLoading}
          pagination
          paginationMode="server"
          rowCount={total}
          initialState={{
            pagination: {
              paginationModel: {
                pageSize: pageSize,
              },
            },
          }}
          onPaginationModelChange={(model) => {
            setPage(model.page);
            setPageSize(model.pageSize);
          }}
          getRowId={(e) => e._id}
        />
      </Card>

      <ExpenseDialog 
        open={open} 
        handleClose={() => setOpen(false)} 
        editData={editData} 
        callApi={callApi}
      />
    </div>
  );
};

export default ExpensePage;

