import * as XLSX from 'xlsx';
import moment from 'moment';

/**
 * Export expense data to Excel with formatting
 * @param {Array} data - Array of expense objects to export
 * @param {String} fileName - Name of the Excel file (without extension)
 * @param {Object} filters - Filter details to show in the export
 */
export const exportExpensesToExcel = (data, fileName = 'Expenses', filters = {}) => {
  try {
    if (!data || data.length === 0) {
      alert('No data to export');
      return;
    }

    // Prepare the expense data with formatted values
    const exportData = data.map((expense) => ({
      'Date': moment(expense.expenseDate).format('DD/MM/YYYY'),
      'Description': expense.description || '',
      'Category': expense.category || '',
      'Amount': expense.amount || 0,
    }));

    // Calculate totals
    const totalAmount = exportData.reduce((sum, item) => sum + item.Amount, 0);

    // Add a summary section
    const summaryData = [
      {},
      { 'Date': 'SUMMARY', 'Description': '', 'Category': '', 'Amount': '' },
      { 'Date': 'Total Expenses', 'Description': '', 'Category': '', 'Amount': totalAmount },
    ];

    // Add filter information if provided
    if (filters.startDate || filters.endDate || filters.description) {
      summaryData.push({});
      summaryData.push({ 'Date': 'FILTERS APPLIED', 'Description': '', 'Category': '', 'Amount': '' });
      
      if (filters.startDate) {
        summaryData.push({
          'Date': `Start Date: ${moment(filters.startDate).format('DD/MM/YYYY')}`,
          'Description': '',
          'Category': '',
          'Amount': '',
        });
      }
      
      if (filters.endDate) {
        summaryData.push({
          'Date': `End Date: ${moment(filters.endDate).format('DD/MM/YYYY')}`,
          'Description': '',
          'Category': '',
          'Amount': '',
        });
      }

      if (filters.description) {
        summaryData.push({
          'Date': `Description: ${filters.description}`,
          'Description': '',
          'Category': '',
          'Amount': '',
        });
      }
    }

    // Combine data
    const finalData = [...exportData, ...summaryData];

    // Create workbook and worksheet
    const ws = XLSX.utils.json_to_sheet(finalData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Expenses');

    // Auto-adjust column widths
    const colWidths = [
      { wch: 15 }, // Date
      { wch: 30 }, // Description
      { wch: 15 }, // Category
      { wch: 15 }, // Amount
    ];
    ws['!cols'] = colWidths;

    // Style the header row
    const headerRow = 0;
    ['A', 'B', 'C', 'D'].forEach((col) => {
      const cellAddress = col + (headerRow + 1);
      if (ws[cellAddress]) {
        ws[cellAddress].s = {
          font: { bold: true, color: { rgb: 'FFFFFF' } },
          fill: { fgColor: { rgb: '4472C4' } },
          alignment: { horizontal: 'center', vertical: 'center' },
        };
      }
    });

    // Style the total row
    const totalRowIndex = exportData.length + 1;
    ['A', 'B', 'C', 'D'].forEach((col) => {
      const cellAddress = col + (totalRowIndex + 2);
      if (ws[cellAddress]) {
        ws[cellAddress].s = {
          font: { bold: true },
          fill: { fgColor: { rgb: 'E7E6E6' } },
          alignment: { horizontal: 'right' },
        };
      }
    });

    // Generate file and trigger download
    XLSX.writeFile(wb, `${fileName}.xlsx`);
  } catch (error) {
    console.error('Error exporting expenses to Excel:', error);
    alert('Failed to export expenses to Excel');
  }
};
